NAME = 'ACV: A Conservative Version'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Razodetje Jezusa Kristusa, ki mu ga je dal Bog, da pokaže hlapcem svojim, kaj se ima skoraj zgoditi; in je poslal angela svojega in po njem to v znamenjih oznanil hlapcu svojemu Janezu,',
        2: 'ki je izpričal besedo Božjo in pričevanje Jezusa Kristusa, karkoli je videl.',
        3: 'Blagor mu, kdor bere in njim, ki slišijo besede prorokovanja in hranijo, kar je v njem pisano, kajti čas je blizu.',
        4: 'Janez sedmerim cerkvam, ki so v Aziji: Milost vam in mir od njega, ki je in ki je bil in ki prihaja, in od sedmerih Duhov, ki so pred prestolom njegovim,',
        5: 'in od Jezusa Kristusa, ki je zvesta priča, prvorojenec izmed mrtvih in poglavar kraljev zemlje. Njemu, ki nas ljubi in nas je omil grehov naših v krvi svoji',
        6: 'in nas je storil v kraljestvo in za duhovnike Bogu in Očetu svojemu, njemu slava in moč na vekov veke! Amen.',
        7: 'Glej, prihaja z oblaki; in videlo ga bo vsako oko in tisti, ki so ga prebodli, in žalovali bodo nad njim vsi rodovi zemlje. Gotovo, amen.',
        8: 'Jaz sem Alfa in Omega, začetek in konec, govori Gospod, Bog, ki je in ki je bil in ki prihaja, Vsemogočni.',
        9: 'Jaz Janez, brat vaš in sodeležnik v stiski in v kraljestvu in stanovitnosti v Jezusu, sem bil na otoku, imenovanem Patmu, zavoljo besede Božje in pričevanja Jezusovega.',
        10: 'Bil sem v Duhu ob dnevi Gospodnjem, in sem slišal za seboj velik glas kakor trombe,',
        11: 'govoreče: Kar vidiš, zapiši v knjigo in pošlji sedmerim cerkvam: v Efez in v Smirno in v Pergam in v Tiatire in v Sarde in v Filadelfijo in v Laodicejo.',
        12: 'In obrnil sem se, da bi videl glas, ki je govoril z menoj; in obrnivši se, sem videl sedem svečnikov zlatih',
        13: 'in sredi svečnikov podobnega sinu človečjemu, oblečenega v obleko do tal in opasanega na prsih z zlatim pasom.',
        14: 'Glava pa njegova in lasje beli kakor bela volna, kakor sneg, in oči njegove kakor plamen ognja,',
        15: 'in noge njegove podobne svetlemu bronu, kakor v peči razbeljenemu, in glas njegov kakor glas mnogih voda;',
        16: 'in v desni roki je imel sedem zvezd, in iz ust njegovih je izhajal dvorezen, oster meč, in obličje njegovo je bilo, kakor ko solnce sije v moči svoji.',
        17: 'In ko sem ga videl, sem padel pred noge njegove kakor mrtev; in položil je name desnico svojo, rekoč: Ne boj se; jaz sem Prvi in Poslednji',
        18: 'in Živi, in bil sem mrtev, in glej, živ sem na vekov veke, in ključe imam od smrti in smrtne države.',
        19: 'Zapiši torej, kar si videl in kar je in kar se ima zgoditi potem,',
        20: 'skrivnost sedmerih zvezd, ki si jih videl v desnici moji, in sedmero svečnikov zlatih. Sedmere zvezde so angeli sedmerih cerkva, in sedmeri svečniki so sedmere cerkve.',
    },
    2: {
        1: 'Angelu cerkve v Efezu piši: To pravi on, ki drži sedmero zvezd v desnici svoji, ki hodi sredi sedmerih svečnikov zlatih:',
        2: 'Vem za dela tvoja in trud tvoj in stanovitnost tvojo, in da ne moreš prenašati hudobnih in si preizkusil nje, ki se imenujejo apostole, a niso, in si jih spoznal kot lažnike;',
        3: 'in stanovitnost imaš in za ime moje si mnogo prenesel in se nisi utrudil.',
        4: 'Toda imam zoper tebe, da si opustil prvo ljubezen svojo.',
        5: 'Spominjaj se torej, odkod si padel, in izpokóri se in delaj prva dela; ako pa ne, ti pridem in premaknem svečnik tvoj z mesta njegovega, če se ne izpokoriš.',
        6: 'Ali to imaš, da sovražiš dela Nikolajcev, ki jih tudi jaz sovražim.',
        7: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam. Njemu, kdor premaga, dam jesti z drevesa življenja, ki je v raju Božjem.',
        8: 'In angelu cerkve v Smirni piši: To pravi Prvi in Poslednji, ki je bil mrtev in je oživel:',
        9: 'Vem za stisko tvojo in uboštvo tvoje (bogat pa si!) in za preklinjanje njih, ki pravijo, da so Judje, a niso, ampak so zbornica Satanova.',
        10: 'Nič se ne boj tega, kar ti bode trpeti. Glej, hudič bo vrgel nekatere izmed vas v ječo, da boste izkušeni, in imeli boste stisko deset dni. Bodi zvest do smrti, in dam ti venec življenja.',
        11: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam. Njemu, kdor premaga, se nič žalega ne zgodi od druge smrti.',
        12: 'In angelu cerkve v Pergamu piši: To pravi on, ki ima meč dvorezni, ostri:',
        13: 'Vem, kje prebivaš, namreč kjer je prestol satanov; in se trdno držiš imena mojega in nisi zatajil vere moje tudi v dneh Antipa, priče moje, zvestega mojega, ki je bil umorjen pri vas, kjer satan prebiva.',
        14: 'Toda imam zoper tebe nekaj malega, da imaš tam nekatere, ki se drže uka Balaamovega, ki je poučil Balaka, naj postavi pohujšanje pred sinove Izraelove, da jedo malikove žrtve in nečistujejo.',
        15: 'Tako jih imaš tudi ti, ki se drže nauka Nikolajcev po podobnem načinu.',
        16: 'Izpokóri se torej; ako pa ne, ti pridem hitro in vojskoval se bom ž njimi z mečem svojih ust.',
        17: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam. Njemu, kdor premaga, dam mane skrite, in mu dam bel kamen in na kamenu zapisano novo ime, ki ga nihče ne pozna, razen kdor ga prejme.',
        18: 'In angelu cerkve v Tiatirih piši: To pravi Sin Božji, ki ima oči kakor plamen ognja, in noge njegove so podobne svetlemu bronu:',
        19: 'Vem za dela tvoja in ljubezen in vero in službo in stanovitnost tvojo ter da je zadnjih del tvojih več nego prvih.',
        20: 'Toda imam zoper tebe, da trpiš ženo Jezabelo, ki se sama imenuje prorokinjo in uči in zapeljuje hlapce moje, da nečistujejo in jedo malikove žrtve.',
        21: 'In dal sem ji časa, da se izpokori, a se noče izpokoriti od nečistosti svoje.',
        22: 'Glej, vržem jo na posteljo in tiste, ki prešuštvujejo ž njo, v stisko veliko, če se ne izpokore od del njenih;',
        23: 'in otroke njene pomorim s smrtjo; in spoznajo vse cerkve, da sem jaz, ki preiskujem obisti in srca, in dam vam vsakemu po delih vaših.',
        24: 'Vam pa pravim, ostalim v Tiatirih, vsem, ki nimajo tega nauka, ki niso spoznali, kakor oni pravijo, globočin satanovih: Ne vržem na vas druge teže.',
        25: 'Toda kar imate, trdno držite, dokler ne pridem.',
        26: 'In njemu, kdor premaga in kdor ohrani do konca dela moja, dam oblast nad narodi,',
        27: 'in pasel jih bo s palico železno, kakor lončarjeve posode bodo strti, kakor sem tudi jaz prejel od Očeta svojega,',
        28: 'in mu dam zvezdo jutranjo.',
        29: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.',
    },
    3: {
        1: 'In angelu cerkve v Sardih piši: To pravi on, ki ima sedmero Duhov Božjih in zvezd sedmero: Vem za dela tvoja, da imaš ime, da živiš, in si mrtev.',
        2: 'Zbudi se in utrdi ostalo, kar je že umiralo. Kajti del tvojih nisem našel popolnih pred Bogom svojim.',
        3: 'Spominjaj se torej, kako si prejel in slišal, ter hrani to in se izpokóri. Ako se torej ne zbudiš, pridem kakor tat in ne boš vedel, ob kateri uri pridem nad tebe.',
        4: 'Ali imaš malo imen v Sardih, kateri niso oskrunili svojih oblačil, in hodili bodo z menoj v belih, ker so vredni.',
        5: 'Kdor premaga, bo tako oblečen v bela oblačila, in nikakor ne izbrišem imena njegovega iz knjige življenja, a pripoznam ime njegovo pred Očetom svojim in pred angeli njegovimi.',
        6: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.',
        7: 'In angelu cerkve v Filadelfiji piši: To pravi Sveti, Resnični, ki ima ključ Davidov, ki odpira, in nihče ne zapre, in zapira, in nihče ne odpre.',
        8: 'Vem za dela tvoja. Glej, postavil sem pred teboj vrata odprta, in nihče jih ne more zapreti, ker majhno imaš moč, in ohranil si besedo mojo in nisi zatajil imena mojega.',
        9: 'Glej, dajem ti jih iz zbornice satanove, ki pravijo, da so Judje, a niso, ampak lažejo; glej, storil bom, da pridejo in pokleknejo pred noge tvoje, in spoznajo, da sem te jaz ljubil.',
        10: 'Ker si ohranil besedo stanovitnosti moje, te ohranim tudi jaz iz ure izkušnjave, ki ima priti na vesoljni svet, izkušat te, ki prebivajo na zemlji.',
        11: 'Hitro pridem; trdno drži, kar imaš, da ti nihče ne vzame venca.',
        12: 'Njega, kdor premaga, naredim za steber v templju Boga svojega, in ven ne pojde več, in zapišem nanj ime Boga svojega in ime mesta Boga svojega, novega Jeruzalema, ki z neba doli gre od Boga mojega, in ime svoje novo.',
        13: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.',
        14: 'In angelu cerkve v Laodiceji piši: To pravi, ki je Amen, priča zvesta in resnična, začetek stvarjenja Božjega:',
        15: 'Vem za dela tvoja, da nisi ne mrzel, ne gorak. Da bi bil mrzel ali gorak!',
        16: 'Tako pa, ker si mlačen in ne mrzel, ne gorak, te hočem izpljuniti iz svojih ust.',
        17: 'Ker praviš: Bogat sem in obogatel sem in ničesar ne potrebujem, in ne veš, da si revež in pomilovanja vreden in ubog in slep in nag,',
        18: 'ti svetujem, da kupiš od mene zlata, očiščenega v ognju, da obogatiš, in bela oblačila, da se oblečeš in da se ne pokaže sramota nagote tvoje, in mazila, da si ž njim pomažeš oči, da bi videl.',
        19: 'Jaz, katerekoli ljubim, svarim in pokorim; razvnemi se torej in se izpokori!',
        20: 'Glej, pri vratih stojim in trkam; če kdo čuje glas moj in odpre vrata, vstopim k njemu, in večerjal bom ž njim in on z menoj.',
        21: 'Njemu, kdor premaga, dam sedeti z menoj na prestolu svojem, kakor sem tudi jaz premagal in sedel z Očetom svojim na prestol njegov.',
        22: 'Kdor ima uho, naj sliši, kaj govori Duh cerkvam.',
    },
    4: {
        1: 'Potem sem videl, in glej: duri odprte na nebu, in prvi glas, ki sem ga slišal kakor glas trombe govoriti z menoj, je dejal: Stopi sem gori, in pokažem ti, kaj se ima zgoditi potem.',
        2: 'Precej sem bil v Duhu; in glej: prestol je postavljen v nebesih',
        3: 'in na prestolu sedi eden; in sedeči je videti podoben kamenu jaspidu in sardu, in mavrica okrog prestola je videti podobna smaragdu.',
        4: 'In okrog prestola štiriindvajset prestolov, in na prestolih vidim štiriindvajsetero starejšin sedečih, oblečenih v bela oblačila, in na njih glavah vence zlate.',
        5: 'In iz prestola izhajajo bliski in glasovi in gromi; in sedem bakel ognjenih gorí pred prestolom, katere so sedmeri Duhovi Božji.',
        6: 'In pred prestolom je kakor morje stekleno, podobno kristalu, in sredi prestola in okrog prestola štiri živali, polne očes spredaj in zadaj.',
        7: 'In prva žival je podobna levu, in druga žival podobna teletu, in tretja žival ima obličje kakor človek, in četrta žival podobna orlu letečemu.',
        8: 'In četvere živali, vsaka zase, imajo po šest peruti in so naokolo in znotraj polne očes; in pokoja nimajo noč in dan, govoreč: Svet, svet, svet, Gospod Bog, Vsegamogočni, ki je bil in ki je in ki prihaja!',
        9: 'In kadar bodo dale živali slavo in čast in hvalo sedečemu na prestolu, živečemu na vekov veke,',
        10: 'bodo padli štiriindvajseteri starejšine pred njega, ki sedi na prestolu, in ga molili, ki živi na vekov veke, in bodo metali vence svoje pred prestol, govoreč:',
        11: 'Vreden si, Gospod in Bog naš, prejemati slavo in čast in moč, zakaj ti si ustvaril vse, in zaradi volje tvoje je bilo vse in je bilo ustvarjeno.',
    },
    5: {
        1: 'In videl sem v desnici sedečega na prestolu knjigo popisano znotraj in zadaj, zapečateno s sedmimi pečati.',
        2: 'In videl sem mogočnega angela, oznanjujočega z velikim glasom: Kdo je vreden odpreti knjigo in odtrgati pečate njene?',
        3: 'In nihče ni mogel ne v nebesih, ne na zemlji, ne pod zemljo odpreti knjige, ne gledati je.',
        4: 'In jaz sem jokal silno, da ni bil nihče za vrednega spoznan odpreti knjige, ne gledati je.',
        5: 'In eden izmed starejšin mi reče: Ne jokaj; glej, zmagal je lev, ki je iz roda Judovega, korenina Davidova, da odpre knjigo in sedmere pečate njene.',
        6: 'In videl sem sredi prestola in četverih živali in sredi starejšin Jagnje stoječe, kakor zaklano, ki je imelo sedem rogov in očes sedem, katera so sedmeri Duhovi Božji, poslani na vso zemljo.',
        7: 'In pride in vzame knjigo iz desnice sedečega na prestolu.',
        8: 'In ko je vzelo knjigo, padejo četvere živali in štiriindvajseteri starejšine pred Jagnjetom, imajoč vsak strune in zlate čaše, polne kadil, ki so molitve svetnikov.',
        9: 'In pojo pesem novo, govoreč: Vreden si prejeti knjigo in odpreti pečate njene; kajti bilo si zaklano in si jih odkupilo Bogu s krvjo svojo iz vsakega rodu in jezika in ljudstva in naroda,',
        10: 'in si jih storilo našemu Bogu v kraljestvo in za duhovnike, in kraljevali bodo na zemlji.',
        11: 'In videl sem in slišal sem glas mnogih angelov okrog prestola in živali in starejšin, in njih število je bilo miriad miriade in tisočev tisoči,',
        12: 'govorečih z velikim glasom: Vredno je Jagnje, ki je bilo zaklano, prejeti moč in bogastvo in modrost in krepkost in čast in slavo in blagoslov.',
        13: 'In vsako stvar, ki je v nebesih in na zemlji in pod zemljo in na morju, in vse, kar je v njih, sem čul govoreče: Sedečemu na prestolu in Jagnjetu blagoslov in čast in slava in moč na vekov veke!',
        14: 'In četvere živali so rekle: Amen! In štiriindvajseteri starejšine so padli in so molili.',
    },
    6: {
        1: 'In videl sem, ko je Jagnje odprlo enega izmed sedmerih pečatov, in slišal sem eno izmed četverih živali govoriti kakor groma glas: Pridi!',
        2: 'In videl sem, in glej: bel konj, in sedeči na njem je imel lok; in dan mu je bil venec, in izšel je zmagovit in da zmaga.',
        3: 'In ko je odprlo drugi pečat, sem slišal drugo žival govoriti: Pridi!',
        4: 'In izšel je drug konj, rjav, in sedečemu na njem je bilo dano vzeti mir z zemlje in da naj se koljejo med seboj; in mu je bil dan velik meč.',
        5: 'In ko je odprlo tretji pečat, sem slišal tretjo žival govoriti: Pridi! In videl sem, in glej: črn konj, in sedeči na njem je imel tehtnico v roki.',
        6: 'In slišal sem kakor glas sredi četverih živali, ki je rekel: Merica pšenice za en denar in tri merice ječmena za en denar; a olju in vinu ne stóri hudega.',
        7: 'In ko je odprlo četrti pečat, sem slišal glas četrte živali govoriti: Pridi!',
        8: 'In videl sem, in glej: bled konj, in sedeči na njem, ime mu Smrt, in smrtno kraljestvo ga spremlja. In mu je bila dana oblast, pomoriti četrtino zemlje z mečem in lakoto in kugo in od zveri zemeljskih.',
        9: 'In ko je odprlo peti pečat, sem videl pod oltarjem duše zaklanih zavoljo besede Božje in zavoljo pričevanja, ki so ga imeli.',
        10: 'In zavpijejo z glasom velikim, rekoč: Doklej, o Gospod, sveti in resnični, ne sodiš in ne maščuješ krvi naše nad njimi, ki prebivajo na zemlji?',
        11: 'In dali so jim vsakemu belo oblačilo in so jim rekli, naj počivajo še malo časa, dokler ne bodo dopolnjeni tudi sohlapci njih in bratje njih, ki imajo biti umorjeni kakor tudi oni.',
        12: 'In videl sem, ko je odprlo šesti pečat, in nastal je velik potres, in solnce je počrnelo kakor vreča raševa, in mesec je pordel ves kakor kri,',
        13: 'in zvezde nebeške so padale na zemljo, kakor trebi smokva nezrelo sadje svoje, ko jo trese velik veter.',
        14: 'In nebo je izginilo kakor knjiga, ko se zvije, in vse gore in otoki so se premeknili s svojih mest.',
        15: 'In kralji zemlje in velikaši in vojaški poveljniki in bogatini in mogočniki in vsak hlapec in svobodnik so se skrili v jame in skalne razpokline po gorah,',
        16: 'in reko goram in skalam: Padite na nas in skrijte nas pred obličjem njega, ki sedi na prestolu, in pred jezo Jagnjetovo,',
        17: 'kajti prišel je velik dan njiju jeze, in kdo more stati?',
    },
    7: {
        1: 'In potem sem videl štiri angele, stoječe na četverih voglih zemlje, držeče četvere vetrove zemlje, da ne veje veter po zemlji, ne po morju, ne čez nobeno drevo.',
        2: 'In videl sem drugega angela, stopajočega gori od solnčnega vzhoda, ki je imel pečat Boga živega; in je zaklical z glasom velikim četverim angelom, ki jim je bilo dano kaziti zemljo in morje,',
        3: 'rekoč: Ne kazite zemlje, ne morja, ne dreves, dokler ne zapečatimo hlapcev Boga našega na njih čelih.',
        4: 'In slišal sem število zapečatenih: stoinštiriinštirideset tisoš zapečatenih iz vseh rodov sinov Izraelovih.',
        5: 'Iz rodu Judovega dvanajst tisoč zapečatenih, iz rodu Rubenovega dvanajst tisoč zapečatenih, iz rodu Gadovega dvanajst tisoč,',
        6: 'iz rodu Aserjevega dvanajst tisoč, iz rodu Neftalimovega dvanajst tisoč, iz rodu Manasejevega dvanajst tisoč,',
        7: 'iz rodu Simeonovega dvanajst tisoč, iz rodu Levijevega dvanajst tisoč, iz rodu Isaharjevega dvanajst tisoč,',
        8: 'iz rodu Zabulonovega dvanajst tisoč, iz rodu Jožefovega dvanajst tisoč, iz rodu Benjaminovega dvanajst tisoč zapečatenih.',
        9: 'Potem sem videl, in glej: velika množica, ki je nihče ni mogel sešteti, iz vsakega naroda in iz vseh rodov in ljudstev in jezikov, stoječe pred prestolom in pred Jagnjetom, oblečene z belimi oblačili in palme v njih rokah,',
        10: 'in kličejo z glasom velikim, rekoč: Zveličanje Bogu našemu, sedečemu na prestolu, in Jagnjetu!',
        11: 'In vsi angeli so stali okrog prestola in starejšin in četverih živali in so padli pred prestolom na obličje in so molili Boga,',
        12: 'rekoč: Amen! Blagoslov in slava in modrost in zahvala in čast in moč in krepkost Bogu našemu na vekov veke! Amen!',
        13: 'In izpregovori eden izmed starejšin, rekoč mi: Kdo so ti, oblečeni z belimi oblačili, in odkod so prišli?',
        14: 'In mu rečem: Gospod moj, ti veš. In mi reče: To so tisti, ki prihajajo iz stiske velike in so oprali oblačila svoja in jih pobelili v krvi Jagnjetovi.',
        15: 'Zato so pred prestolom Božjim in mu služijo noč in dan v svetišču njegovem, in sedeči na prestolu razpne svoj šator nad njimi.',
        16: 'Lačni ne bodo več, ne žejni več, tudi solnce jih ne zadene, ne vročina nobena;',
        17: 'kajti Jagnje, ki je sredi prestola, jih bo paslo in jih vodilo k studencem voda življenja; in Bog obriše vsako solzo ž njih oči.',
    },
    8: {
        1: 'In ko je odprlo sedmi pečat, je nastal molk v nebesih za kake pol ure.',
        2: 'In videl sem sedmere angele, ki stoje pred Bogom; in bilo jim je danih sedem tromb.',
        3: 'In drug angel je prišel in stopil pred oltar, držeč zlato kadilnico; in mu je bilo dano mnogo kadil, da jih daruje z molitvami vseh svetih na oltarju zlatem pred prestolom.',
        4: 'In šel je kvišku dim kadil z molitvami svetih iz roke angelove pred Boga.',
        5: 'In angel vzame kadilnico in jo napolni z ognjem z oltarja in vrže na zemljo; in nastali so gromi in glasovi in bliski in potres.',
        6: 'In sedmeri angeli, ki so imeli sedmere trombe, se pripravijo, da zatrobijo.',
        7: 'In prvi zatrobi in nastane toča in ogenj, namešana s krvjo, in je bila vržena na zemljo; in tretjina zemlje je pogorela in tretjina dreves je pogorela in vsa trava zelena je pogorela.',
        8: 'In drugi angel zatrobi, in kakor gora velika, z ognjem goreča, je bila vržena v morje; in tretjina morja postane kri,',
        9: 'in tretjina stvari, ki so v morju in imajo življenje, pomrje in tretjina ladij se razbije.',
        10: 'In tretji angel zatrobi, in z neba pade zvezda velika, goreča kakor bakla, in pade na tretjino rek in na studence vodá;',
        11: 'in ime zvezde se imenuje Pelin, in tretjina voda postane pelin in mnogo ljudi je umrlo od voda, ker so bile ogrenele.',
        12: 'In četrti angel zatrobi, in udarjena je bila tretjina solnca in tretjina meseca in tretjina zvezd, da otemni tretjina njih in dan ne sije, tretjina njegova, in noč enako.',
        13: 'In videl sem in slišal sem enega orla, letečega po sredi neba, govoriti z glasom velikim: Gorje, gorje, gorje prebivalcem na zemlji zaradi ostalih glasov trombe treh angelov, ki imajo še trobiti.',
    },
    9: {
        1: 'In peti angel zatrobi, in videl sem zvezdo, z neba padlo na zemljo, in dan ji je bil ključ k žrelu brezna.',
        2: 'In odpre žrelo brezna; in privali se dim iz žrela kakor dim peči velike, in solnce in zrak otemnita od dima iz žrela.',
        3: 'In iz dima izidejo kobilice na zemljo, in dá se jim oblast, kakor imajo oblast škorpijoni zemlje.',
        4: 'In reče se jim, naj ne store hudega travi zemlje, ne kaki zelenjavi, ne kakemu drevesu, razen ljudem samim, ki nimajo pečata Božjega na čelih.',
        5: 'In dá se jim, da naj jih ne pomore, temuč da naj jih mučijo pet mesecev; in njih mučenje je kakor mučenje škorpijona, kadar piči človeka.',
        6: 'In v tistih dneh bodo iskali ljudje smrti, a ne bodo je našli; in želeli bodo umreti, a smrt bo bežala od njih.',
        7: 'In podobe kobilic so bile enake konjem, pripravljenim na vojsko, in na njih glavah kakor venci, podobni zlatu, in obličja njih kakor obličja človeška;',
        8: 'in lase so imele kakor lase ženske in njih zobje so bili kakor levov;',
        9: 'in imele so oklepe kakor oklepe železne; in šum njih peruti kakor ropotanje mnogih voz s konji, tekočimi v vojsko;',
        10: 'in imajo repe enake škorpijonom in žela; in v repih jim je njih oblast, škodovati ljudem mesecev pet.',
        11: 'In nad seboj imajo za kralja angela brezna; ime mu je po hebrejsko: Abadon, in po grško ima ime: Apolion.',
        12: 'Gorje eno je prešlo; glej, še dvoje Gorje potem.',
        13: 'In šesti angel zatrobi, in slišal sem eden glas iz četverih rogov oltarja zlatega pred Bogom,',
        14: 'kateri je rekel šestemu angelu, ki je imel trombo: Reši četvere angele, zvezane ob reki veliki, Evfratu.',
        15: 'In odvezani so bili četveri angeli, ki so bili pripravljeni na uro in dan in mesec in leto, da pomore tretjino ljudi.',
        16: 'In število vojsk konjištva je bilo dve miriadi miriad; slišal sem njih število.',
        17: 'In tako sem videl konje v prikazni in na njih sedeče, ki so imeli oklepe ognjene in temnordeče in žveplene; in glave konj kakor glave levov in iz njih ust izhaja ogenj in dim in žveplo.',
        18: 'Te tri šibe so pomorile tretjino ljudi, ogenj in dim in žveplo, ki izhaja iz njih ust.',
        19: 'Kajti moč konj je v njih ustih in v njih repih; njih repi namreč so enaki kačam, imajo glave in s temi škodijo.',
        20: 'In ostali ljudje, ki niso bili pomorjeni s temi šibami, se še niso izpokorili od del svojih rok, da bi ne molili zlih duhov in malikov zlatih in srebrnih in bronastih in kamenitih in lesenih, kateri ne morejo ne gledati ne slišati, ne hoditi,',
        21: 'in niso se izpokorili od moritev svojih, ne od čaranj in ne od nečistosti in ne od tatvin svojih.',
    },
    10: {
        1: 'In videl sem drugega angela mogočnega iti doli z neba, ogrnjenega z oblakom, in mavrica na glavi njegovi, in obličje njegovo kakor solnce in nogi njegovi kakor stebra ognjena.',
        2: 'In imel je v roki knjižico odprto. In postavil je desno nogo na morje, levo pa na zemljo,',
        3: 'in je zavpil z glasom velikim, kakor rjove lev. In ko je zavpil, so govorili sedmeri gromovi glasove svoje.',
        4: 'In ko so sedmeri gromovi dogovorili, sem hotel pisati; a slišal sem glas z neba, govoreč: Zapečati, kar so govorili sedmeri gromovi, in ne piši tega.',
        5: 'In angel, ki sem ga videl stoječega na morju in na zemlji, vzdigne roko proti nebu',
        6: 'in priseže pri njem, ki živi na vekov veke, ki je ustvaril nebo in kar je na njem, in zemljo in kar je na njej, in morje in kar je v njem: Podaljšanja časa ne bo več,',
        7: 'temuč v dneh glasu sedmega angela, ko bo trobil, se tudi dopolni skrivnost Božja, kakor je oznanil v blagovestju hlapcem svojim prorokom.',
        8: 'In glas, ki sem ga slišal z neba, je zopet govoril z menoj in rekel: Pojdi, vzemi knjižico, odprto v roki angela, stoječega na morju in na zemlji.',
        9: 'In šel sem k angelu in mu rekel, naj mi da knjižico. In mi reče: Vzemi in pojej jo! in zagrenila ti bo trebuh, a v ustih tvojih bode sladka kakor med.',
        10: 'In vzamem knjižico iz roke angelove in jo pojem; in bila je v ustih mojih kakor med sladka, a ko sem jo bil pojedel, mi je zagrenel trebuh.',
        11: 'In mi reče: Zopet moraš prorokovati o ljudstvih in narodih in jezikih in kraljih mnogih.',
    },
    11: {
        1: 'In dan mi je bil trst, podoben palici, in mi je bilo rečeno: Vstani in izmeri svetišče Božje in oltar in tiste, ki molijo v njem.',
        2: 'A dvor, ki je zunaj svetišča, vrzi ven in ga ne meri; ker je bil dan poganom in bodo teptali sveto mesto dvainštirideset mesecev.',
        3: 'In dal bom dvema pričama svojima, in prorokovala bosta tisoč dvesto šestdeset dni, oblečena v raševnika.',
        4: 'To sta oljki dve in svečnika dva, stoječa pred Gospodom zemlje.',
        5: 'In če jima hoče kdo storiti kaj žalega, izide jima ogenj iz ust in požre njune sovražnike; in če jima bo hotel kdo kaj žalega storiti, mora enako biti umorjen.',
        6: 'Ta imata oblast, nebo zapreti, da ne dežuje v dneh njunega prorokovanja; in oblast imata nad vodami, izpremeniti jih v kri in udariti zemljo z vsako šibo, kolikorkrat bosta hotela.',
        7: 'In kadar dokončata pričevanje svoje, napravi zver, ki prihaja gori iz brezna, vojsko ž njima in ju zmaga in umori.',
        8: 'In trupli njuni bosta ležali na ulicah mesta velikega, ki se imenuje duhovno Sodoma in Egipt, kjer je bil tudi njiju Gospod križan.',
        9: 'In gledali bodo nekateri iz ljudstev in rodov in jezikov in narodov trupli njuni tri dni in pol, in trupel njunih ne bodo pustili dejati v grobe.',
        10: 'In prebivalci na zemlji se bodo veselili nad njima in se radovali, in dari si bodo pošiljali med seboj, ker sta ta dva proroka mučila prebivalce na zemlji.',
        11: 'In po treh dneh in pol je prišel življenja duh iz Boga vanju in sta stopila na noge, in strah velik je prešel tiste, ki so ju gledali.',
        12: 'In slišala sta glas velik z neba, rekoč jima: Pojdita sem gori! In šla sta gori na nebo v oblaku, in videli so ju sovražniki njuni.',
        13: 'In v tisti uri je nastal potres velik, in desetina mesta je padla, in pobitih je bilo v potresu sedem tisoč ljudi; in kar jih je ostalo, so se prestrašili in so dali slavo Bogu nebes.',
        14: 'Gorje drugo je prešlo; glej, Gorje tretje pride hitro!',
        15: 'In sedmi angel zatrobi, in nastanejo glasovi veliki v nebesih, govoreči: Kraljestvo sveta je postalo kraljestvo Gospoda našega in Kristusa njegovega, in kraljeval bo na vekov veke.',
        16: 'In štiriindvajseteri starejšine, ki sede pred Bogom na prestolih svojih, so padli na obličja in molili Boga, rekoč:',
        17: 'Zahvaljujemo te, Gospod Bog, Vsegamogočni, ki si in ki si bil, da si prejel moč veliko svojo in si zakraljeval.',
        18: 'In narodi so se razsrdili, in prišla je jeza tvoja in čas mrtvih, da bodo sojeni, in da se dá plačilo hlapcem tvojim prorokom in svetnikom in njim, ki se boje imena tvojega, malim in velikim, in da se pogube, kateri pogubljajo zemljo.',
        19: 'In odpre se svetišče Božje, ki je v nebesih, in skrinja zaveze njegove se je videla v svetišču njegovem; in nastali so bliski in glasovi in gromovi in potres in toča velika.',
    },
    12: {
        1: 'In znamenje veliko se je videlo na nebu: žena, oblečena s solncem, in mesec pod njenimi nogami in na njeni glavi venec dvanajsterih zvezd;',
        2: 'in noseča je in kriči v bolečinah in mukah porodnih.',
        3: 'In videlo se je drugo znamenje na nebu, in glej: zmaj velik, ognjen, imajoč sedem glav in rogov deset, in na glavah njegovih sedem diademov,',
        4: 'in rep njegov potegne s seboj tretjino zvezd nebeških in jih vrže na zemljo. In zmaj stopi pred ženo, ki ima poroditi, da požre dete njeno, ko ga porodi.',
        5: 'In rodila je sina, moža, ki bo pasel vse narode s palico železno; in njeno dete je bilo vzeto k Bogu in k prestolu njegovemu.',
        6: 'In žena je bežala v puščavo, kjer ima kraj pripravljen od Boga, da jo tam žive dni tisoč dvesto šestdeset.',
        7: 'In nastala je vojska v nebesih: Mihael in angeli njegovi so se vojskovali zoper zmaja. In zmaj se je vojskoval in angeli njegovi,',
        8: 'a niso zmogli; tudi njih mesto se ni več našlo v nebesih.',
        9: 'In vržen je bil zmaj veliki in kača stara, ki se imenuje Hudič in Satan, ki zapeljava vesoljni svet, vržen je bil na zemljo, in angeli njegovi so bili vrženi ž njim.',
        10: 'In slišal sem glas velik v nebesih, govoreč: Zdaj je prišlo zveličanje in moč in kraljestvo Boga našega in oblast Kristusa njegovega, ker vržen je doli naših bratov tožnik, ki jih je tožil pred Bogom našim noč in dan.',
        11: 'In oni so ga premagali zavoljo krvi Jagnjetove in zavoljo besede pričevanja svojega, in niso ljubili življenja svojega prav do smrti.',
        12: 'Zato veselite se, nebesa in kateri stanujete v njih! Gorje zemlji in morju, ker doli je šel Hudič k vam, z veliko jezo, ker ve, da ima malo časa.',
        13: 'In ko je videl zmaj, da je vržen na zemljo, je preganjal ženo, ki je rodila moškega.',
        14: 'In dali so ženi dve peruti orla velikega, da poleti v puščavo, na kraj svoj, kjer se živi čas in dva časa in pol časa, daleč od obličja kače.',
        15: 'In kača je vrgla iz ust svojih zadaj za ženo vodo kakor reko, da bi jo reka odnesla.',
        16: 'A pomogla je ženi zemlja, in odprla je zemlja usta svoja in popila reko, ki jo je bil vrgel zmaj iz svojih ust.',
        17: 'In razsrdi se zmaj nad ženo in gre napravljat vojsko z ostalimi semena njenega, ki hranijo zapovedi Božje in imajo pričevanje Jezusa Kristusa.',
    },
    13: {
        1: 'In postavi se na pesku morskem. In videl sem iz morja zver vzhajajočo, ki je imela deset rogov in sedem glav, in na rogovih njenih deset diademov in na glavah njenih imena preklinjevanja.',
        2: 'In zver, ki sem jo videl, je bila podobna pardalu, in noge njene kakor medvedove in usta njena kakor usta levova. In dal ji je zmaj moč svojo in prestol svoj in oblast veliko.',
        3: 'In videl sem eno izmed glav njenih kakor zaklano na smrt. In njena smrtna rana se je zacelila, in vsa zemlja se je čudila zadaj za zverjo;',
        4: 'in molili so zmaja, ker je bil dal oblast zveri, in molili so zver, govoreč: Kdo je zveri enak? In kdo se more vojskovati ž njo?',
        5: 'In dana so ji usta, govoreča stvari velike in preklinjevanja, in dana ji je bila oblast, da deluje štirideset mesecev in dva.',
        6: 'In odprla je usta svoja v preklinjanje proti Bogu, preklinjajoča ime njegovo in šator njegov in nje, ki stanujejo v nebesih.',
        7: 'In dano ji je bilo napraviti vojsko s svetimi in jih premagati; in dana ji je oblast nad vsakim rodom in ljudstvom in jezikom in narodom.',
        8: 'In molili jo bodo vsi, ki prebivajo na zemlji, vsak, čigar ime ni zapisano v knjigi življenja Jagnjeta zaklanega od ustanovitve sveta.',
        9: 'Če ima kdo uho, naj sliši.',
        10: 'Če kdo v robstvo vodi, v robstvo hodi. Če bo kdo z mečem moril, mora umorjen biti z mečem. Tukaj je stanovitnost in vera svetnikov.',
        11: 'In videl sem drugo zver vzhajajočo iz zemlje, in imela je dva rogova, kakor jagnje, a govorila je kakor zmaj.',
        12: 'In vso oblast prve zveri izvršuje pred njo. In dela, da zemlja in prebivalci njeni molijo prvo zver, ki se ji je bila zacelila rana smrti njene.',
        13: 'In dela znamenja velika, da napravi tudi, da šviga ogenj z neba na zemljo pred ljudmi.',
        14: 'In zapeljava prebivalce na zemlji z znamenji, katera ji je bilo dano delati pred zverjo, rekoč prebivalcem na zemlji, naj narede podobo zveri, ki je imela rano od meča in je oživela.',
        15: 'In dano ji je bilo vdihniti duha podobi zveri, da tudi govori podoba zveri in stori, da bodo pomorjeni, katerikoli ne molijo podobe zveri.',
        16: 'In stori, da si dado vsi, mali in veliki, bogati in ubogi, svobodni in hlapci, znamenje na desno roko ali na čelo,',
        17: 'in da nihče ne more kupovati ali prodajati, razen kdor ima znamenje, ime zveri ali število imena njenega.',
        18: 'Tukaj je modrost. Kdor ima razum, naj izračuni število zveri; je namreč število človeka. In število njegovo je šeststo šestdeset in šest.',
    },
    14: {
        1: 'In videl sem, in glej: Jagnje stoječe na gori Sionu in ž njim stoštiriinštirideset tisoči, ki imajo ime njegovo in ime Očeta njegovega zapisano na čelih svojih.',
        2: 'In slišal sem glas iz nebes kakor glas mnogih vodá in kakor groma velikega glas; in glas, ki sem ga slišal, je bil kakor citralcev, citrajočih na citre svoje.',
        3: 'In pojo kakor pesem novo pred prestolom in pred četverimi živalmi in starejšinami; in nihče se ni mogel naučiti pesmi razen stoštiriinštiridesetih tisoči, ki so odkupljeni od zemlje.',
        4: 'Ti so, kateri se niso oskrunili z ženami; device so namreč. Ti so, ki hodijo za jagnjetom, kamorkoli gre. Ti so bili odkupljeni izmed ljudi, prvina Bogu in Jagnjetu.',
        5: 'In v njih ustih se ni našla laž, brez madeža so.',
        6: 'In videl sem drugega angela, letečega po sredi neba, ki je imel večen evangelij, da ga oznani prebivalcem na zemlji in vsakemu narodu in rodu in jeziku in ljudstvu,',
        7: 'govorečega z glasom velikim: Bojte se Boga in dajte mu slavo, kajti prišla je ura sodbe njegove; in molite njega, ki je naredil nebo in zemljo in morje in studence vodá.',
        8: 'In drug je šel za njim, drugi angel, govoreč: Padel je, padel Babilon, mesto véliko, ki je z vinom srda nečistosti svoje napojilo vse narode.',
        9: 'In drug pride za njima, tretji angel, govoreč z glasom velikim: Če kdo moli zver in podobo njeno in vzame njeno znamenje na čelo ali na roko svojo,',
        10: 'bo tudi on pil od vina srda Božjega, ki je čisto pripravljeno v čaši jeze njegove, in se bo mučil v ognju in žveplu pred svetimi angeli in pred Jagnjetom.',
        11: 'In njih mučenja dim vzhaja na vekov veke, in pokoja nimajo noč in dan, kateri molijo zver in podobo njeno in kdor sprejme znamenje njenega imena.',
        12: 'Tukaj je stanovitnost svetnikov, kateri hranijo zapovedi Božje in vero Jezusovo.',
        13: 'In slišal sem glas z neba, rekoč: Piši: Blagor mrtvim, ki umrjejo v Gospodu od sedaj. Da, pravi Duh, odpočijejo se naj od trudov svojih, zakaj njih dela gredo za njimi.',
        14: 'In videl sem, in glej: bel oblak in na oblaku sedeč eden, podoben sinu človečjemu, imajoč na glavi venec zlat in v roki oster srp.',
        15: 'In drug angel pride iz svetišča, vpijoč z glasom velikim sedečemu na oblaku: Spusti srp svoj in žanji, kajti prišla je žetve ura, ker prezrela je žetev zemlje.',
        16: 'In sedeči na oblaku vrže srp svoj na zemljo, in požeta je bila zemlja.',
        17: 'In drug angel pride iz svetišča, ki je v nebesih, in tudi on ima oster srp.',
        18: 'In drug angel pride od oltarja, imajoč oblast nad ognjem, in zavpije z glasom velikim njemu, ki ima srp ostri, rekoč: Spusti srp svoj ostri in odreži grozdje trte zemeljske, kajti dozorele so jagode njene.',
        19: 'In angel vrže srp svoj na zemljo, in rezal je grozdje trte zemeljske in metal v veliko tlačilnico jeze Božje.',
        20: 'In tlačila se je tlačilnica zunaj mesta, in tekla je kri iz tlačilnice prav do vajetov konj tisoč šeststo tečajev daleč.',
    },
    15: {
        1: 'In videl sem drugo znamenje v nebesih, veliko in čudovito: sedem angelov, imajočih sedmero šib poslednjih, ker se je v njih dopolnila jeza Božja.',
        2: 'In videl sem kakor morje stekleno, namešano z ognjem, in zmagovalce nad zverjo in nad podobo njeno in nad številom njenega imena, stoječe ob morju steklenem s citrami Božjimi.',
        3: 'In pojo pesem Mojzesa, hlapca Božjega, in pesem Jagnjetovo, govoreč: Velika in čudovita so dela tvoja, o Gospod Bog, Vsegamogočni, pravična in resnična pota tvoja, o Kralj narodov!',
        4: 'Kdo bi se te ne bal, Gospod, in ne slavil tvojega imena? ker sam si svet; kajti vsi narodi bodo prišli in molili pred teboj, ker razodela so se pravična dela tvoja.',
        5: 'In potem sem videl, in odpre se svetišče šatora pričevanja v nebesih,',
        6: 'in pridejo iz svetišča sedmeri angeli, ki imajo sedmero šib, oblečeni v platno čisto in svetlo ter opasani okoli prsi z zlatimi pasi.',
        7: 'In ena iz četverih živali dá sedmerim angelom sedem čaš zlatih, polnih jeze Boga živega na vekov veke.',
        8: 'In napolni se svetišče dima od slave Božje in od moči njegove; in nihče ni mogel iti v svetišče, dokler se ne dokončajo sedmere šibe sedmerih angelov.',
    },
    16: {
        1: 'In slišal sem glas velik iz svetišča, govoreč sedmerim angelom: pojdite in izlijte sedmere čaše jeze Božje na zemljo.',
        2: 'In odide prvi ter izlije čašo svojo na zemljo; in pride uljé hudo in strupeno na ljudi, ki so imeli znamenje zveri in ki so molili podobo njeno.',
        3: 'In drugi angel izlije čašo svojo v morje; in postane kri kakor kri mrliča, in umrje vsaka duša živa, kar jih je v morju.',
        4: 'In tretji angel izlije čašo svojo v reke in studence vodá, in naredi se kri.',
        5: 'In slišal sem angela vodá govorečega: Pravičen si, Gospod, ki si in ki si bil, Sveti, da si tako sodil:',
        6: 'ker kri svetnikov in prerokov so prelivali, in krvi si jim dal piti; vredni so tega.',
        7: 'In slišal sem oltar reči: Da, Gospod, Bog, Vsegamogočni, resnične in pravične so sodbe tvoje.',
        8: 'In četrti angel izlije čašo svojo na solnce; in dalo se mu je sežgati ljudi v ognju.',
        9: 'In žgali so se ljudje v silni vročini in preklinjali ime Boga, ki ima oblast do teh šib, in niso se izpokorili, da bi mu slavo dajali.',
        10: 'In peti izlije čašo svojo na prestol zveri; in kraljestvo njeno je otemnelo, in grizli so si jezike od muke',
        11: 'in preklinjali Boga nebeškega od muk in od uljés svojih, in niso se izpokorili od svojih del.',
        12: 'In šesti izlije čašo svojo na reko veliko, Evfrat; in posuši se voda njena, da se pripravi pot kraljem, ki pridejo od solnčnega vzhoda.',
        13: 'In videl sem izhajati iz ust zmajevih in iz ust zveri in iz ust lažiproroka tri nečiste duhove, enake žabam;',
        14: 'so namreč duhovi hudičev, ki delajo znamenja; ti izhajajo na kralje vesoljnega sveta, da jih zbero na vojsko tistega velikega dne Boga, Vsegamogočnega.',
        15: '(Glej, pridem kakor tat; blagor mu, kdor čuje in hrani oblačila svoja, da ne hodi nag in ne gledajo sramote njegove).',
        16: 'In zbrali so jih na kraj, imenovan po hebrejsko: Harmagedon.',
        17: 'In sedmi izlije čašo svojo v zrak; in prišel je glas velik iz svetišča, od prestola, rekoč: Zgodilo se je!',
        18: 'In nastanejo bliski in glasovi in gromi, in nastane potres velik, kakršnega ni bilo, odkar so bili ljudje na zemlji, tolik potres, tako grozen!',
        19: 'In mesto veliko se raztrga na tri dele, in mesta narodov padejo; in Babilon veliki je prišel v spomin pred Bogom, da se mu da čaša vina srda in jeze njegove.',
        20: 'In vsi otoki so bežali in gorá ni bilo najti.',
        21: 'In toča velika, kakor talent težka, pada z neba na ljudi; in ljudje so preklinjali Boga zaradi šibe toče, ker silno težka je šiba njena.',
    },
    17: {
        1: 'In prišel je eden iz sedmerih angelov, ki imajo sedmere čaše, in je govoril z menoj, rekoč: Sem! pokažem ti sodbo nečistnice vélike, sedeče na mnogih vodah,',
        2: 's katero so nečistovali kralji zemeljski, in z vinom nečistosti njene so se opijanili zemlje prebivalci.',
        3: 'In odnese me v puščavo v Duhu; in videl sem ženo, sedečo na zveri škrlatni, polni imen preklinjanja, imajoči sedem glav in rogov deset.',
        4: 'In žena je bila oblečena v bager in v škrlat in pozlačena z zlatom in dragim kamenjem in biseri; imela je zlat kozarec v roki, poln gnusob in nečistosti kurbarstva svojega;',
        5: 'in na čelu ji je bilo ime zapisano, skrivnost: Babilon véliki, mati nečistnic in gnusob zemlje!',
        6: 'In videl sem to ženo pijano krvi svetnikov in krvi pričevalcev Jezusovih. In videč jo, sem se silno čudil.',
        7: 'In angel mi reče: Zakaj se čudiš? Jaz ti povem skrivnost žene in zveri, ki jo nosi, ki ima sedem glav in rogov deset.',
        8: 'Zver, ki si jo videl, je bila in je ni, in priti ima gori iz brezna in iti v pogubo; in prebivalci na zemlji, katerih imena niso zapisana v knjigi življenja od ustanovitve sveta, se bodo čudili, gledajoč zver, da je bila in je ni, a zopet pride.',
        9: 'Tukaj razum, ki ima modrost: sedmero glav je sedem gorá, kjer žena sedi na njih;',
        10: 'in je kraljev sedem: pet jih je padlo in eden je, drugi še ni prišel, in kadar pride, sme malo časa ostati.',
        11: 'In zver, ki je bila in je ni, je sam tudi osmi in je izmed sedmerih in gre v pogubo.',
        12: 'In desetero rogov, ki si jih videl, je deset kraljev, ki še niso prejeli kraljestva, ali prejmo oblast kot kralji za eno uro z zverjo vred.',
        13: 'Ti imajo eno misel, in moč in oblast svojo izročé zveri.',
        14: 'Ti se bodo vojskovali z Jagnjetom, in Jagnje jih bo zmagalo, ker je gospodov Gospod in kraljev Kralj, in ž njim bodo zmagali poklicani in izvoljeni in zvesti.',
        15: 'In reče mi: Vode, ki si jih videl, kjer sedi nečistnica, so ljudstva in množice in narodi in jeziki.',
        16: 'In deseteri rogovi, ki si jih videl, in zver, ti bodo sovražili nečistnico in jo naredili pusto in nago ter meso njeno pojedli in njo sežgali v ognju.',
        17: 'Kajti Bog je dal v njih srca, da storé misel njegovo in da store eno misel in dado kraljestvo svoje zveri, dokler se ne izvršé besede Božje.',
        18: 'In žena, ki si jo videl, je mesto véliko, ki ima kraljestvo nad kralji zemlje.',
    },
    18: {
        1: 'Potem sem videl drugega angela iti doli z neba, ki je imel oblast veliko; in zemlja se je razsvetlila od slave njegove.',
        2: 'In zavpije z močnim glasom, rekoč: Padel je, padel Babilon veliki, in postal je prebivališče hudičev in ječa vseh nečistih duhov in ječa vseh nečistih in sovraženih ptičev.',
        3: 'Kajti od vina srda nečistosti njene so pili vsi narodi, in kralji zemeljski so nečistovali ž njo, in trgovci zemlje so obogateli od silne bujnosti njene.',
        4: 'In slišal sem drug glas z nebes, govoreč: Izidite iz nje, ljudstvo moje, da se ne udeležite grehov njenih in da ne prejmete od njenih šib;',
        5: 'kajti grehi njeni so se nakopičili do neba, in Bog se je spomnil krivic njenih.',
        6: 'Vrnite ji, kakor je tudi ona vračala, in podvojite ji dvojno po delih njenih; v kozarec, v katerega je mešala, namešajte ji dvojno.',
        7: 'Kolikor se je poveličala in prešerno živela, toliko ji dajte muke in žalosti. Kajti v srcu svojem govori: Kraljica sedim in vdova nisem, in žalosti ne bom videla.',
        8: 'Zato pridejo v enem dnevu šibe njene, smrt in žalost in lakota, in v ognju bo sežgana; kajti močan je Gospod, Bog, ki jo je sodil.',
        9: 'In jokali bodo in žalovali zanjo kralji zemlje, kateri so nečistovali ž njo in prešerno živeli, ko bodo videli dim požara njenega,',
        10: 'od daleč stoječ v strahu pred muko njeno in govoreč: Gorje, gorje, mesto veliko, Babilon, mesto močno! ker v eni uri je prišla sodba tvoja.',
        11: 'In trgovci zemlje jokajo in žalujejo za njo, ker njih blaga ne kupuje nihče več:',
        12: 'blaga iz zlata in srebra in dragega kamenja in biserov in tenčice in bagra in svile in škrlata, in vsakterega lesa dišečega in vsakterega orodja slonokoščenega in vsakterega orodja iz lesa predragega in brona in železa in marmorja,',
        13: 'in sladke skorje in tujih korenin in dišav in mire in kadila, in vina in olja in bele moke in pšenice, in goved in ovac, in konj in voz in sužnjev in duš človeških.',
        14: 'In sadje, ki si ga je želela duša tvoja, je odšlo od tebe, in vse tolsto in sijajno ti je izginilo, in nikdar več jih nihče ne najde.',
        15: 'Trgovci s temi rečmi, ki so obogateli od nje, bodo stali oddaleč v strahu pred muko njeno, jokajoč in žalujoč in govoreč:',
        16: 'Gorje, gorje, mesto véliko, ki je bilo oblečeno v tenčico in v bager in škrlat in pozlačeno z zlatom in dragim kamenjem in biseri!',
        17: 'kajti v eni uri je izničeno toliko bogastvo. In vsi krmarji in vsak, kdor se kam vozi v ladji, in brodniki in katerikoli imajo opravila na morju, so stali oddaleč',
        18: 'in vpili, videč dim požara njenega, in govorili: Katero je enako temu mestu vélikemu?',
        19: 'In vrgli so si prahu na glave in so vpili, jokajoč in žalujoč in govoreč: Gorje, gorje, mesto véliko, v katerem so obogateli vsi, ki imajo ladje na morju, vsled potratnosti njegove! kajti v eni uri je opustošeno.',
        20: 'Veselite se njega, nebesa, in svetniki in apostoli in proroki, ker je Bog sodil sodbo vašo nad njim.',
        21: 'In en angel, močan, je vzdignil kamen, velik kakor mlinski kamen, in ga vrgel v morje, rekoč: Tako siloma bo doli vržen Babilon, mesto veliko, in ne bode ga več.',
        22: 'In glas citralcev in godcev in piskačev in trobentačev se ne bo nikdar več slišal v tebi, in noben umetnik kake umetnosti se ne prikaže nikdar več v tebi, in mlina glas se ne bo nikdar več čul v tebi,',
        23: 'in svetilnice luč nikoli več ne bo svetila v tebi, in glas ženina in neveste se ne bo nikdar več čul v tebi; kajti trgovci tvoji so bili velikaši zemlje; in s čarodejstvom tvojim so bili zapeljani vsi narodi.',
        24: 'In v njem se je našla kri prorokov in svetnikov in vseh, ki so bili zaklani na zemlji.',
    },
    19: {
        1: 'In potem sem slišal kakor močan glas velike množice v nebesih, rekoč: Aleluja! zveličanje in slava in moč Bogu našemu,',
        2: 'kajti resnične in pravične so sodbe njegove; zakaj sodil je nečistnico véliko, ki je pačila zemljo z nečistostjo svojo, in hlapcev svojih kri je maščeval na roki njeni.',
        3: 'In drugič so rekli: Aleluja! In dim njen vzhaja na vekov veke.',
        4: 'In padli so starejšine štiriindvajseteri in četvere živali in so molili Boga, sedečega na prestolu, rekoč: Amen, Aleluja!',
        5: 'In glas je prišel od prestola, govoreč: Hvalite Boga našega, vsi hlapci njegovi, ki se ga bojite, mali in véliki!',
        6: 'In slišal sem kakor glas množice velike in kakor glas mnogih vodá in kakor glas močnih gromov, govorečih: Aleluja! ker zakraljeval je Gospod, Bog naš, Vsegamogočni.',
        7: 'Veselimo se in radujmo in dajajmo slavo njemu; ker prišlo je ženitvovanje Jagnjetovo, in nevesta njegova se je pripravila.',
        8: 'In dano ji je bilo, da se obleče v tenčico, svetlo in čisto; tenčica namreč so pravična dela svetnikov.',
        9: 'In mi veli: Piši: Blagor jim, kateri so poklicani k večerji ženitvovanja Jagnjetovega! In mi reče: To so resnične besede Božje.',
        10: 'In padel sem pred noge njegove, da ga molim. In mi reče: Glej, da tega ne storiš! hlapec sem s teboj vred in s tvojimi brati, ki imajo pričevanje Jezusovo, Boga móli! Kajti pričevanje Jezusovo je duh prorokovanja.',
        11: 'In videl sem nebesa odprta, in glej: bel konj in sedeči na njem imenovan Zvesti in Resnični, in v pravičnosti sodi ter se vojskuje.',
        12: 'Oči njegove pa so plamen ognjen, in na glavi njegovi mnogi diademi, in zapisano ima ime, ki ga nihče ne zna razen njega samega.',
        13: 'In ogrnjen je z oblačilom, omočenim s krvjo, in imenuje se ime njegovo: Beseda Božja.',
        14: 'In vojske, ki so v nebesih, so šle za njim na belih konjih, oblečene v tenčico belo in čisto.',
        15: 'In iz ust njegovih izhaja oster meč, da ž njim udarja narode; in on jih bo pasel s šibo železno, in on tlači tlačilnico vina srda in jeze Boga, Vsegamogočnega.',
        16: 'In ima na obleki in na bedru svojem ime zapisano: KRALJ KRALJEV IN Gospodov Gospod.',
        17: 'in videl sem enega angela, stoječega v solncu, in zavpil je z glasom velikim, rekoč vsem ptičem, ki letajo po sredi neba: Pridite in zberite se k veliki večerji Božji,',
        18: 'da jeste meso kraljev in meso vojaških poveljnikov in meso mogočnih in meso konj in sedečih na njih in meso vseh, svobodnih in hlapcev, malih in velikih.',
        19: 'In videl sem zver in kralje zemlje in njih vojske zbrane, da se vojskujejo s sedečim na konju in z vojsko njegovo.',
        20: 'In zgrabljena je bila zver in ž njo lažiprorok, ki je delal pred njo znamenja, s katerimi je zapeljeval nje, ki so bili sprejeli znamenje zveri in ki so molili podobo njeno; živa sta bila vržena ta dva v jezero ognjeno, z žveplom goreče.',
        21: 'In drugi so bili pomorjeni z mečem sedečega na konju, s tistim, ki je izhajal iz ust njegovih; in vsi ptiči so se napasli ž njih mesom.',
    },
    20: {
        1: 'In videl sem angela iti doli iz nebes, imajočega ključ od brezna in verigo veliko na roki svoji.',
        2: 'In zgrabi zmaja, staro kačo, ki je hudič in satan; in zveže ga za tisoč let in ga vrže v brezno in zapre in zapečati nad njim, da ne zapeljuje več narodov, dokler se ne izpolni tisoč let.',
        3: 'Potem se mora izpustiti za malo časa.',
        4: 'In videl sem prestole, in sedli so nanje in dana jim je bila sodba; in videl sem duše obglavljenih zaradi pričevanja Jezusovega in zaradi besede Božje in tiste, ki niso molili zveri, ne podobe njene, in niso sprejeli znamenja na čelo in na roko svojo: in oživeli so ter kraljevali s Kristusom tisoč let.',
        5: 'Drugi mrtvi pa niso oživeli, dokler se ne izpolni tisoč let. To je vstajenje prvo.',
        6: 'Blažen in svet, kdor ima delež v prvem vstajenju; do teh druga smrt nima oblasti, marveč duhovniki bodo Božji in Kristusovi, in bodo ž njim kraljevali tisoč let.',
        7: 'In ko se izpolni tisoč let, bo izpuščen satan iz ječe svoje,',
        8: 'in izide zapeljevat narode, ki so na četverih voglih zemlje, Goga in Magoga, da jih zbere na vojsko; katerih število je kakor peska v morju.',
        9: 'In šli so gori na zemlje širjavo in so obkrožili šatorišče svetnikov in mesto ljubljeno; in prišel je ogenj od Boga z neba in požrl jih je.',
        10: 'In hudič, ki jih je zapeljaval, je bil vržen v jezero ognjeno in žvepleno, kjer sta tudi zver in lažiprorok; in mučili se bodo noč in dan na vekov veke.',
        11: 'In videl sem bel prestol, velik, in sedečega na njem, ki mu je izpred obličja bežala zemlja in nebo, in ni se jima našlo mesto.',
        12: 'In videl sem mrtve, velike in male, stoječe pred prestolom, in knjige so se odprle; in druga knjiga se je odprla, ki je knjiga življenja. In sojeni so bili mrtvi po tem, kar je bilo pisano v knjigah, po delih svojih.',
        13: 'In dalo je morje mrtve, ki so bili v njem, in smrt in smrtna država sta dali mrtve, ki so bili v njiju, in sojeni so bili, vsak po delih svojih.',
        14: 'In smrt in smrtna država sta bili vrženi v jezero ognjeno. To je smrt druga, jezero ognjeno.',
        15: 'In če koga niso našli zapisanega v knjigi življenja, je bil vržen v jezero ognjeno.',
    },
    21: {
        1: 'In videl sem novo nebo in zemljo novo; kajti prvo nebo in prva zemlja sta bila prešla, in morja ni več.',
        2: 'In videl sem mesto sveto, Jeruzalem novi, da gre navzdol od Boga iz nebes, napravljeno kakor nevesta, odičena ženinu svojemu.',
        3: 'In slišal sem glas velik od prestola, da govori: Glej, šator Božji z ljudmi, in prebival bo ž njimi; in oni bodo ljudstva njegova, in Bog sam bode med njimi, njih Bog,',
        4: 'in obriše vse solze ž njih oči; in smrti ne bode več, ne žalovanja, ne vpitja, ne bolečine ne bode več; kajti prvo je prešlo.',
        5: 'In rekel je sedeči na prestolu: Glej, novo delam vse. In mi veli: Piši, ker te besede so resnične in zveste.',
        6: 'In mi reče: Zgodilo se je. Jaz sem Alfa in Omega, začetek in konec. Jaz bom dal žejnemu iz studenca vode življenja brezplačno.',
        7: 'Kdor premaga, bo to podedoval, in bodem mu Bog in on mi bode sin.',
        8: 'Strahopetnim pa in nevernim in ostudnim in morilcem in nečistnikom in čarovnikom in malikovalcem in vsem lažnivcem, njim je delež v jezeru, gorečem z ognjem in žveplom, kar je druga smrt.',
        9: 'In pride eden izmed sedmerih angelov, ki so imeli sedmero čaš, polnih sedmerih šib poslednjih, in je govoril z menoj, rekoč: Sem! pokažem ti nevesto, ženo Jagnjetovo.',
        10: 'In odnese me v Duhu na goro veliko in visoko in mi pokaže sveto mesto, Jeruzalem, ki gre doli od Boga iz nebes,',
        11: 'imajoč slavo Božjo. In svetloba njegova je enaka kamenu predragemu, kakor kamenu jaspidu, čistemu kot kristal;',
        12: 'ima zid velik in visok in ima dvanajstero vrat, in ob vratih angelov dvanajst in imena na njih zapisana, katera so dvanajsterih rodov sinov Izraelovih:',
        13: 'proti vzhodu troje vrat, proti severu troje vrat, proti jugu troje vrat, proti zahodu troje vrat.',
        14: 'In zid mestni ima temeljnih kamenov dvanajst, in na njih dvanajst imen dvanajsterih apostolov Jagnjetovih.',
        15: 'In z menoj govoreči je imel merilo zlato, da izmeri mesto in vrata njegova in zid njegov.',
        16: 'In mesto je zidano na štiri vogle, in dolžina njegova tolikšna, kolikršna tudi širjava. In izmeril je mesto z merilom na dvanajst tisoč tečajev; dolžina in širjava in višava so enake.',
        17: 'In izmeril je zid njegov na stoinštiriinštirideset lahti, po človeški meri, ki je angelova.',
        18: 'In zid njegov je zidan iz jaspida, in mesto je čisto zlato, enako steklu čistemu.',
        19: 'Temeljni kameni zidu mestnega so odičeni z vsakovrstnim dragim kamenjem: temelj prvi jaspid, drugi safir, tretji kalcedon, četrti smaragd,',
        20: 'peti sardoniks, šesti sard, sedmi hrizolit, osmi beril, deveti topaz, deseti hrizopraz, enajsti hiacint, dvanajsti ametist.',
        21: 'In dvanajstera vrata dvanajst biserov; vsaka vrata so bila iz enega bisera. In ulice mestne čisto zlato, kakor steklo prozorno.',
        22: 'A svetišča nisem videl v njem, kajti Gospod, Bog, Vsegamogočni, je svetišče njegovo in Jagnje.',
        23: 'In mesto ne potrebuje solnca, ne meseca, da svetita v njem; zakaj slava Božja ga je razsvetlila, in svetilnica njegova je Jagnje.',
        24: 'In narodi bodo hodili po svetlobi njegovi, in kralji zemlje nosijo slavo svojo vanje.',
        25: 'In vrata njegova se ne zaklenejo podnevi, noči namreč tam ne bode;',
        26: 'in zneso slavo in čast narodov vanje.',
        27: 'In ne pride vanje nič nečistega, ne kdor dela gnusobo in laž, samo kateri so zapisani v življenja knjigi Jagnjetovi.',
    },
    22: {
        1: 'In pokazal mi je reko vode življenja, svetlo kakor kristal, izhajajočo iz prestola Božjega in Jagnjetovega.',
        2: 'Sredi ulic njegovih ter na to in ono stran reke je drevo življenja, ki rodi sadov dvanajst, vsak mesec dajoč sad svoj, in listje drevesno je v ozdravljenje narodov.',
        3: 'In nobenega prokletstva ne bode več. In prestol Božji in Jagnjetov bode v njem; in hlapci njegovi mu bodo služili,',
        4: 'in gledali bodo obličje njegovo, in ime njegovo bo na njih čelih.',
        5: 'In noči ne bode več, in potreba jim ni svetilnice in luči solnčne, ker jim bo svetil Gospod, Bog; in kraljevali bodo na vekov veke.',
        6: 'In reče mi: Te besede so zveste in resnične, in Gospod, Bog duhov proroških, je poslal angela svojega, pokazat hlapcem svojim, kaj se ima zgoditi skoraj.',
        7: 'In glej, hitro pridem. Blagor mu, kdor hrani besede prorokovanja te knjige!',
        8: 'In jaz Janez sem, ki sem videl to in slišal. In ko sem slišal in videl, sem padel pred nogami angela, ki mi je to kazal, da bi ga molil.',
        9: 'In reče mi: Glej, da tega ne storiš! hlapec sem s teboj vred in z brati tvojimi proroki in ž njimi, ki hranijo besede te knjige; Boga móli!',
        10: 'In mi veli: Ne zapečati besed prorokovanja te knjige, ker čas je blizu.',
        11: 'Kdor dela krivico, naj jo dela še, in kdor je nesnažen, bodi še nesnažen; in kdor je pravičen, delaj še bolj pravico, in sveti naj se še bolj posvečuje.',
        12: 'Glej, pridem hitro in plačilo moje z menoj, da povrnem vsakemu, kakor je delo njegovo.',
        13: 'Jaz sem Alfa in Omega, prvi in poslednji, začetek in konec.',
        14: 'Blagor jim, ki pero oblačila svoja, da imajo oblast do drevesa življenja in da gredo skozi vrata v mesto.',
        15: 'Zunaj bodo psi in čarovniki in nečistniki in morilci in malikovalci in vsak, kdor ljubi in dela laž.',
        16: 'Jaz Jezus sem poslal angela svojega, pričat vam to po cerkvah. Jaz sem korenina in rod Davidov, svetla zvezda jutranja.',
        17: 'In Duh in nevesta govorita: Pridi! In kdor sliši, naj reče: Pridi! In kdor je žejen, pridi; kdor hoče, vzemi vodo življenja brezplačno.',
        18: 'Pričam vsakemu, kdor sliši besede prorokovanja te knjige: Ako kdo k temu kaj pristavi, njemu pridene Bog šib, ki so zapisane v tej knjigi.',
        19: 'In ako kdo kaj odvzame od besed knjige tega prorokovanja, odvzame Bog delež njegov od drevesa življenja in iz mesta svetega, od tega, kar je pisano v tej knjigi.',
        20: 'On, ki to priča, pravi: Gotovo, pridem hitro. Amen, pridi, Gospod Jezus!',
        21: 'Milost Gospoda Jezusa bodi z vsemi svetimi. Amen.',
    },
}
